import zipfile,re
z=zipfile.ZipFile('slides/LWT介绍.pptx')
pages=len([n for n in z.namelist() if re.match(r'ppt/slides/slide\d+\.xml$',n)])
pts=0
for n in z.namelist():
    if re.match(r'ppt/slides/charts/chart\d+\.xml$',n):
        xml=z.read(n).decode('utf-8','replace')
        for val in re.findall(r'<c:val>.*?</c:val>',xml,re.S):
            pts+=val.count('<c:pt ')
print('OK' if pages==21 and pts==12 else f'MISS pages={pages} points={pts}')
